-- The Raidergang — Stage 2: exercise + throwing drill libraries
-- Source: 'Coaching Database (Organized)' Google Sheet, Exercise Library and
-- Throwing Drill Library tabs, as reviewed by the coaches (Nov 2026).
-- Safe to re-run: existing names are skipped.

create table if not exists public.exercise_categories (
  category    text not null,
  subcategory text not null,
  sort_order  int  not null,
  primary key (category, subcategory)
);
alter table public.exercise_categories enable row level security;
drop policy if exists "signed-in see categories" on public.exercise_categories;
create policy "signed-in see categories" on public.exercise_categories for select to authenticated using (public.me() is not null);
drop policy if exists "editors manage categories" on public.exercise_categories;
create policy "editors manage categories" on public.exercise_categories for all to authenticated
  using (public.coach_can_edit()) with check (public.coach_can_edit());
grant select, insert, update, delete on public.exercise_categories to authenticated;

on conflict do nothing;

on conflict ((lower(name))) do nothing;

on conflict ((lower(name))) do nothing;
